            aWandererJ = aWandererJ ^ ((RotL64(aPrevious, 57U) + RotL64(aOrbiterI, 23U)) + aOrbiterJ);
            aWandererA = aWandererA + (((RotL64(aIngress, 48U) + aOrbiterF) + RotL64(aOrbiterK, 41U)) + aWUSaltG[(((511U - aIndex) + 479U)) & S_SALT1]);
            aWandererE = aWandererE ^ ((RotL64(aCross, 41U) + RotL64(aOrbiterA, 27U)) + aOrbiterC);
