            aOrbiterJ = ((aWandererH + RotL64(aCross, 34U)) + RotL64(aCarry, 53U)) + 0x11D5F1A3BE0CCEF2ULL;
            aOrbiterK = ((aWandererJ + RotL64(aIngress, 29U)) + RotL64(aCarry, 23U)) + 0x4A2BCA6724F9A999ULL;
