            aOrbiterC = ((aWandererK + RotL64(aScatter, 13U)) + 0xBE71B3224CDECFB5ULL) + aOASaltB[(((511U - aIndex) + 90U)) & S_SALT1];
            aOrbiterB = ((aWandererG + RotL64(aCross, 47U)) + 0x6F1E5E4CCEE3633BULL) + aOASaltH[(((511U - aIndex) + 401U)) & S_SALT1];
