            //
            aOrbiterG = (aOrbiterG + aOrbiterC) + 0xBA8BB075E244D256ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterG) ^ 0x1F808AB5C24C4B3DULL) ^ aOUSaltD[((aIndex + 111U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x4A40BCDE44B5E323ULL), 13U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterG) + 0xF94558E68F229268ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterH) ^ 0x1262529B395B190AULL;
            aOrbiterB = RotL64((aOrbiterB * 0x7DC945294BAC8267ULL), 37U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterH) + 0x713EBA99BCC6F421ULL) + aOUSaltB[(((511U - aIndex) + 248U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterC) ^ 0x4E77E0C262266D38ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x2ADCC834B74816B3ULL), 57U);
