            //
            aOrbiterK = ((aOrbiterK + aOrbiterB) + 0x044988BB15BC9EF5ULL) + aOUSaltG[((aIndex + 206U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0x49ED3018F78159BAULL;
