            aOrbiterG = (aOrbiterG ^ aOrbiterD) ^ 0xD144A770B0571067ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xF78F3720E7086FDDULL), 27U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterD) + 0x812289C630B314C9ULL;
