            //
            aOrbiterA = (aWandererC + RotL64(aIngress, 5U)) + 0x43B56593CAE9FA72ULL;
            aOrbiterC = ((aWandererG + RotL64(aCross, 29U)) + 0x6E085AB616B7CF7AULL) + aOASaltA[((aIndex + 167U)) & S_SALT1];
            aOrbiterI = (aWandererE + RotL64(aScatter, 57U)) + 0x84A496E3B7A1216DULL;
            aOrbiterJ = ((aWandererH + RotL64(aPrevious, 3U)) + RotL64(aCarry, 5U)) + 0xF2FD3C3EA6D11F64ULL;
            aOrbiterG = ((aWandererF + RotL64(aIngress, 36U)) + 0x40BF7E760CD9AD3CULL) + aOASaltC[(((511U - aIndex) + 250U)) & S_SALT1];
            aOrbiterK = (aWandererB + RotL64(aCross, 23U)) + 0x2896395C19AC2AA3ULL;
            aOrbiterF = (aWandererI + RotL64(aPrevious, 21U)) + 0x281B52AAB505220DULL;
            aOrbiterB = (((aWandererJ + RotL64(aScatter, 51U)) + RotL64(aCarry, 35U)) + 0xA0BD528ADAF4EE5AULL) + aOASaltH[((aIndex + 429U)) & S_SALT1];
            aOrbiterE = ((aWandererK + RotL64(aCross, 11U)) + RotL64(aCarry, 19U)) + 0x3FA30B105C568E8BULL;
            aOrbiterD = ((aWandererD + RotL64(aIngress, 47U)) + 0x1259D514F32DF9DBULL) + aOASaltD[(((511U - aIndex) + 338U)) & S_SALT1];
