            aOrbiterG = (((aWandererE + RotL64(aPrevious, 5U)) + RotL64(aCarry, 37U)) + 0x1327DB2F4AE303D3ULL) + aOASaltE[((aIndex + 207U)) & S_SALT1];
            aOrbiterD = (aWandererK + RotL64(aCross, 35U)) + 0x67ECC2A2F97F3765ULL;
