            //
            aIngress = (RotL64(aWindLaneD[((aIndex + 4457U)) & S_BLOCK1], 51U) ^ RotL64(aWindLaneB[((aIndex + 1550U)) & S_BLOCK1], 19U));
            aIngress ^= (RotL64(aShadowLaneB[((aIndex + 5011U)) & S_BLOCK1], 5U) ^ RotL64(aShadowLaneA[((S_BLOCK1 - aIndex + 4439U)) & S_BLOCK1], 30U));
            aIngress = TwistMix64::DiffuseC((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aWindLaneC[((S_BLOCK1 - aIndex + 5630U)) & S_BLOCK1], 14U) ^ RotL64(aWindLaneA[((S_BLOCK1 - aIndex + 6217U)) & S_BLOCK1], 39U));
            aCross ^= (RotL64(aLightningLaneA[((S_BLOCK1 - aIndex + 3823U)) & S_BLOCK1], 51U) ^ RotL64(aShadowLaneC[((aIndex + 1882U)) & S_BLOCK1], 3U));
            aCross = TwistMix64::DiffuseA((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aCross, 21U) + RotL64(aIngress, 35U)) ^ (RotL64(aCarry, 52U) ^ RotL64(aPrevious, 3U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterH = ((aWandererH + RotL64(aIngress, 11U)) + RotL64(aCarry, 39U)) + 0xCAC8F174C40707D5ULL;
            aOrbiterB = ((aWandererD + RotL64(aCross, 52U)) + 0xCC64E8A1A765BA99ULL) + aOASaltG[(((511U - aIndex) + 262U)) & S_SALT1];
            aOrbiterK = ((aWandererG + RotL64(aPrevious, 3U)) + 0x2FDAEF57A1AB833CULL) + aOASaltD[(((511U - aIndex) + 293U)) & S_SALT1];
            aOrbiterD = ((aWandererF + RotL64(aScatter, 29U)) + 0x3622B5EFDAEB9929ULL) + aOASaltE[(((511U - aIndex) + 472U)) & S_SALT1];
            aOrbiterI = (aWandererK + RotL64(aCross, 37U)) + 0xF8180B2638A8BE9CULL;
            aOrbiterF = (((aWandererB + RotL64(aPrevious, 21U)) + RotL64(aCarry, 23U)) + 0xCF6E612E43C87898ULL) + aOASaltB[(((511U - aIndex) + 9U)) & S_SALT1];
            aOrbiterE = (((aWandererA + RotL64(aScatter, 43U)) + RotL64(aCarry, 53U)) + 0x3C163E5A16B8BA91ULL) + aOASaltA[((aIndex + 297U)) & S_SALT1];
            //
            aOrbiterH = ((aOrbiterH + aOrbiterB) + 0x9367CC233CA327A6ULL) + aOUSaltF[(((511U - aIndex) + 155U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterH) ^ 0xB2641DEC6A65F494ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x390FAAAF50F32B29ULL), 19U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterI) + 0xB6F108623E244D21ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterD) ^ 0x72E6824ECF9C580DULL;
            aOrbiterH = RotL64((aOrbiterH * 0x688B36745B333075ULL), 11U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterF) + 0x0EEA965852695DCAULL) + aOUSaltG[(((511U - aIndex) + 197U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterI) ^ 0x2FBCD6873C7AD3CCULL;
            aOrbiterB = RotL64((aOrbiterB * 0xA282FA1550D757F3ULL), 3U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterD) + 0xBDA44C74C940ADC4ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterB) ^ 0x5C92EDADA37CD8DBULL;
            aOrbiterE = RotL64((aOrbiterE * 0x896DC31194267B5FULL), 37U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterH) + 0xFBF372D64A6DBB31ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterE) ^ 0xC97926636203BA8EULL) ^ aOUSaltC[((aIndex + 17U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x15A3E91027811099ULL), 47U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterK) + 0x48A91F2C6F49A82BULL) + aOUSaltA[(((511U - aIndex) + 219U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0x0E6EFD08F21E0D55ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x90B9269571E58C2BULL), 29U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterE) + 0x9B773AA7CD5D348BULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0x7EB1A89EBB75D715ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x6F9A70303BD68E31ULL), 53U);
            //
            aIngress = aOrbiterB ^ RotL64(aOrbiterF, 47U);
            aIngress = aIngress + (RotL64(aOrbiterH, 5U) ^ aOrbiterI);
            aIngress = aIngress + (aOrbiterE ^ RotL64(aOrbiterK, 57U));
            aIngress = aIngress + RotL64(aOrbiterD, 20U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererK = aWandererK + ((((RotL64(aCross, 35U) + aOrbiterE) + RotL64(aOrbiterK, 29U)) + RotL64(aCarry, 5U)) + aWUSaltA[((aIndex + 56U)) & S_SALT1]);
            aWandererA = aWandererA ^ (((RotL64(aScatter, 58U) + RotL64(aOrbiterK, 41U)) + aOrbiterI) + aWUSaltE[(((511U - aIndex) + 112U)) & S_SALT1]);
            aWandererF = aWandererF + ((((RotL64(aPrevious, 51U) + RotL64(aOrbiterD, 13U)) + aOrbiterB) + RotL64(aCarry, 47U)) + aWUSaltC[((aIndex + 95U)) & S_SALT1]);
            aWandererD = aWandererD ^ ((RotL64(aIngress, 21U) + aOrbiterK) + RotL64(aOrbiterF, 5U));
            aWandererG = aWandererG + (((RotL64(aCross, 29U) + aOrbiterD) + RotL64(aOrbiterI, 47U)) + aWUSaltH[((aIndex + 123U)) & S_SALT1]);
            aWandererH = aWandererH ^ ((RotL64(aIngress, 11U) + aOrbiterE) + RotL64(aOrbiterH, 58U));
            aWandererB = aWandererB + ((RotL64(aPrevious, 43U) + aOrbiterF) + RotL64(aOrbiterD, 21U));
            //
