            aScatter = (RotL64(aCross, 39U) ^ RotL64(aPrevious, 56U)) + (RotL64(aIngress, 5U) ^ RotL64(aCarry, 23U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateBDomainWordScatter));
            //
            aOrbiterJ = ((aWandererH + RotL64(aScatter, 41U)) + RotL64(aCarry, 5U)) + 0x6C92967B3867DDF1ULL;
            aOrbiterB = ((aWandererD + RotL64(aCross, 10U)) + 0x2128815647B92CFAULL) + aOASaltE[((aIndex + 205U)) & S_SALT1];
            aOrbiterI = ((aWandererA + RotL64(aPrevious, 53U)) + 0x8198DEA4ED3BBA39ULL) + aOASaltG[(((511U - aIndex) + 139U)) & S_SALT1];
