            aOrbiterA = (((aWandererI + RotL64(aCross, 35U)) + RotL64(aCarry, 35U)) + 0x04E94B6C3E221C6EULL) + aOASaltC[((aIndex + 354U)) & S_SALT1];
            aOrbiterH = (aWandererB + RotL64(aPrevious, 27U)) + 0x45C387C091659F18ULL;
            aOrbiterD = ((aWandererC + RotL64(aScatter, 3U)) + 0xAAC2362D32BBCEF9ULL) + aOASaltD[(((511U - aIndex) + 473U)) & S_SALT1];
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterB) + 0x3C21C7C4F92CE869ULL) + aOUSaltC[(((511U - aIndex) + 118U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterJ) ^ 0x9E63D82C53A56884ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x2F26A785C3A9846FULL), 19U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterA) + 0x182D7F271774CC18ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterE) ^ 0x3D67ECDFCC57AC11ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x026F2039D878B851ULL), 53U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterI) + 0x21A1D07A6644BE7AULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterH) ^ 0x4B6487D165519FC5ULL;
