            //
            aOrbiterD = ((aOrbiterD + aOrbiterJ) + 0x526D393564886A76ULL) + aOUSaltB[((aIndex + 67U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterD) ^ 0x98CEF41251E9E9B3ULL) ^ aOUSaltE[((aIndex + 28U)) & S_SALT1];
