            aOrbiterK = (((aWandererK + RotL64(aScatter, 21U)) + RotL64(aCarry, 47U)) + 0x75ECEF2275038D02ULL) + aOASaltC[((aIndex + 491U)) & S_SALT1];
            aOrbiterE = ((aWandererG + RotL64(aIngress, 57U)) + 0x17F6D5BFB9FAB8D9ULL) + aOASaltF[(((511U - aIndex) + 220U)) & S_SALT1];
            aOrbiterC = (((aWandererB + RotL64(aCross, 47U)) + RotL64(aCarry, 23U)) + 0x86FA5A11E4B3C675ULL) + aOASaltA[(((511U - aIndex) + 358U)) & S_SALT1];
