            aOrbiterC = ((aOrbiterC + aOrbiterE) + 0x54B0AA732DB7DF17ULL) + aOUSaltG[(((511U - aIndex) + 339U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterC) ^ 0x3765AD22CEEA2A1CULL) ^ aOUSaltE[(((511U - aIndex) + 69U)) & S_SALT1];
