            aOrbiterK = (aOrbiterK + aOrbiterG) + 0x7B638350D236DB4EULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterK) ^ 0x82278F6B57DC9580ULL) ^ aOUSaltH[((aIndex + 355U)) & S_SALT1];
